const products = rows.map(
  (
    [
      slug,
      name,
      category,
      productType,
      material,
      price,
      originalPrice,
      colour,
      size,
      capacity,
      weight,
      stock,
      ageDays,
      flags,
      shortDescription,
      description,
      features,
      highlights,
    ],
    i,
  ) => {
    const t = TYPE[productType];
    const specifications = [
      ["Material", material],
      ["Colour", colour],
      ["Size", size],
      ["Capacity", capacity],
      ["Weight", weight],
      ["Care", t.care],
    ]
      .filter(([, v]) => v)
      .map(([key, value]) => ({ key, value }));
    return {
      name,
      slug,
      sku: `BW-${t.prefix}-${String(i + 1).padStart(3, "0")}`,
      shortDescription,
      description,
      price,
      originalPrice,
      category,
      productType,
      material,
      colour,
      size,
      capacity,
      weight,
      specifications,
      features,
      highlights: highlights.map(([key, value]) => ({ key, value })),
      images: [1, 2, 3]
        .map((n) => `/images/products/${slug}-${n}.jpg`)
        .filter(imageExists),
      stock,
      featured: flags.includes("f"),
      bestSeller: flags.includes("b"),
      premium: flags.includes("p"),
      sold: flags.includes("b") ? 80 + ((i * 37) % 120) : (i * 11) % 60,
      ageDays,
    };
  },
);

categories.forEach((category) => {
  if (!imageExists(category.image)) {
    const firstProduct = products.find((p) => p.category === category.slug);
    category.image = firstProduct?.images[0] ?? category.image;
  }
});

